def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    threat_bids = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('budget', 0) > 0:
                    threat_bids.append(float(bid))

    if not alive:
        return float(min(budget, 18.0))

    expected_winners = max(1, int(supply // WATER_REQ))
    live_count = len(alive) + 1
    scarcity = live_count - expected_winners

    highest_prev = max(prev_bids) if prev_bids else 0.0
    highest_threat = max(threat_bids) if threat_bids else highest_prev

    urgent = hp <= 3 or no_water >= 1
    severe = hp <= 2 or no_water >= 2

    base = 0.0

    if severe:
        base = max(62.0, highest_threat + 2.5)
    elif urgent:
        if scarcity >= 3:
            base = max(54.0, highest_threat + 1.5)
        else:
            base = max(46.0, highest_threat * 0.72 + 2.0)
    else:
        if scarcity >= 4:
            base = max(44.0, highest_threat * 0.55 + 1.0)
        elif scarcity >= 2:
            base = max(32.0, highest_threat * 0.38 + 1.0)
        else:
            base = 18.0

    if day >= 8:
        base += 6.0
    elif day >= 5 and urgent:
        base += 4.0

    reserve_days = max(0, 10 - day)
    reserve_floor = reserve_days * 16.0
    affordable = max(0.0, budget - reserve_floor)

    if severe and affordable < 35.0:
        affordable = budget
    elif urgent and affordable < 25.0:
        affordable = max(affordable, budget * 0.75)

    bid = min(base, budget, max(0.0, affordable))

    if bid <= 0.0:
        if severe:
            bid = min(budget, 55.0)
        elif urgent:
            bid = min(budget, 35.0)
        else:
            bid = min(budget, 12.0)

    if highest_threat >= 120.0 and not urgent:
        bid = min(bid, 24.0)

    return float(max(0.0, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0))
    no_water_days = int(my_status.get('no_water_days', 0))

    # Determine alive opponents and read yesterday bids
    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    # If no opponents are alive, bid conservatively
    if not alive_opps:
        cap = min(budget, DAILY_SALARY * 0.4)
        return max(0.0, cap)

    yesterday_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # If we can infer competitive pressure from yesterday
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        avg_prev_bid = sum(yesterday_bids) / float(len(yesterday_bids))
    else:
        highest_prev_bid = 0.0
        avg_prev_bid = 0.0

    # Base target: aim around the upper-middle of yesterday bids without matching the absolute max
    # Cindy avg ~129.8, David avg ~97.6; choose a level that should win against most but save budget.
    # Adjust for our urgency.
    urgency = 0
    if hp <= 2:
        urgency = 2
    elif hp <= 4:
        urgency = 1
    if no_water_days >= 2:
        urgency = max(urgency, 1)

    # Supply pressure: higher supply reduces need to overbid.
    # Convert supply to a 0..1 scale
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_scale = (supply - float(MIN_SUPPLY)) / float(MAX_SUPPLY - MIN_SUPPLY)
    else:
        supply_scale = 0.5
    supply_scale = max(0.0, min(1.0, supply_scale))

    # Start from a competitive anchor derived from yesterday
    # If highest bid was very high, we slightly undercut it; otherwise anchor to avg.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        anchor = highest_prev_bid * (0.92 - 0.04 * supply_scale)
    else:
        anchor = max(avg_prev_bid, DAILY_SALARY * 0.55) * (0.92 - 0.06 * supply_scale)

    # Urgency pushes bid upward
    bid = anchor
    if urgency == 2:
        bid = max(bid, DAILY_SALARY * 0.85)
    elif urgency == 1:
        bid = max(bid, DAILY_SALARY * 0.65)

    # If we are likely to lose (budget low), cap aggressively
    # Ensure bid never exceeds budget
    bid = min(bid, budget)

    # Also keep within a reasonable upper bound to avoid bankruptcy
    # (since this game likely uses salary as a natural scale)
    bid_cap = min(budget, DAILY_SALARY * 1.2)
    bid = min(bid, bid_cap)

    # If budget is extremely small, just bid what we can
    if budget <= 1e-6:
        return 0.0

    # Final safeguard: bid at least 0
    return max(0.0, float(bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    base_bid = DAILY_SALARY * 0.75

    remaining_days = EPISODE_DAYS - day_context['day']
    if remaining_days <= 2:
        base_bid = DAILY_SALARY * 0.9
    elif day_context['day'] <= 2:
        base_bid = DAILY_SALARY * 0.65

    if my_status['hp'] <= 2:
        base_bid = DAILY_SALARY * 0.95
    elif my_status['hp'] <= 4:
        base_bid = max(base_bid, DAILY_SALARY * 0.85)

    if day_context['supply'] <= (MIN_SUPPLY + MAX_SUPPLY) / 2:
        base_bid = max(base_bid, DAILY_SALARY * 0.8)

    if yesterday_bids:
        max_prev_bid = max(yesterday_bids)
        if max_prev_bid >= DAILY_SALARY * 0.8:
            base_bid = max(base_bid, max_prev_bid + 5)
        elif max_prev_bid >= DAILY_SALARY * 0.5:
            base_bid = max(base_bid, max_prev_bid + 2)
        else:
            base_bid = max(base_bid, max_prev_bid + 1)

    final_bid = min(my_status['budget'], base_bid)

    return max(0.0, final_bid)
